B.GB=new A.du("ASK FOR THE ARCHIVE SEAL",B.LQ,B.Mg,"archive_seal",null,"archivist_seal",null,null,null,"archive_seal")
B.Mw=A.a(s(["I wrote that line so no one else would have to. It did not save them.","Go. If your Gaia is different, prove it. If she is not \u2014 I will finish what I started."]),t.s)
B.KA=A.a(s(["audio/voices/voss_confront_1.mp3","audio/voices/voss_confront_2.mp3"]),t.s)
B.GC=new A.du("CONFRONT HIM WITH THE ORDERS",B.Mw,B.KA,null,"confronted_voss_orders",null,null,null,null,null)
B.KR=A.a(s(["Then walk with open eyes. The Archivist holds a seal you may need."]),t.s)
