B.GD=new A.du("PROMISE TO REMEMBER THE CHOOSING",B.KR,B.KP,null,"promised_echo",null,null,null,"promised_echo",null)
B.Kh=A.a(s(["Then we're still on the same side. Go. Make him hear a people \u2014 not a ghost story."]),t.s)
