B.GE=new A.du("PROMISE TO CARRY THE NAMES",B.Kh,B.Kw,null,"asha_archive_ack",null,null,null,null,null)
B.K6=A.a(s(["Browse the stall \u2014 salvage and colony trinkets. Pay with glimmer from jobs and finds."]),t.s)
